import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Datenbank, Benutzer und Ordner verstehen","description":"","frontmatter":{"title":"Datenbank, Benutzer und Ordner verstehen","source_pageid":1121,"source_revision":5914},"headers":[],"relativePath":"einstieg/grundlagen/faq.md","filePath":"einstieg/grundlagen/faq.md"}'),a={name:"einstieg/grundlagen/faq.md"};function s(d,e,h,l,c,u){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="datenbank-benutzer-und-ordner-verstehen" tabindex="-1">Datenbank, Benutzer und Ordner verstehen <a class="header-anchor" href="#datenbank-benutzer-und-ordner-verstehen" aria-label="Permalink to &quot;Datenbank, Benutzer und Ordner verstehen&quot;">​</a></h1><p>Klären Sie die Begriffe Datenbankschema, Benutzerrolle und Installationsordner. Die Antworten helfen dabei, die Zuständigkeiten von MariaDB, SVWS-Server und SchILD-NRW 3 zu unterscheiden.</p><h2 id="datenbank-und-installation" tabindex="-1">Datenbank und Installation <a class="header-anchor" href="#datenbank-und-installation" aria-label="Permalink to &quot;Datenbank und Installation&quot;">​</a></h2><h3 id="was-ist-ein-datenbank-schema" tabindex="-1">Was ist ein Datenbank-Schema? <a class="header-anchor" href="#was-ist-ein-datenbank-schema" aria-label="Permalink to &quot;Was ist ein Datenbank-Schema?&quot;">​</a></h3><p>Ein <strong>Datenbankschema</strong> bezeichnet hier die Datenbank einer Schule innerhalb der MariaDB. Es enthält die von SVWS benötigten Tabellen und kann leer, bereits befüllt oder aus SchILD-NRW 2 migriert sein. „Schema“ bedeutet daher nicht, dass noch keine Schuldaten vorhanden sind.</p><p>In einer MariaDB können mehrere Schemata liegen, die dann einer einzelnen SVWS-Datenbank einer Schule entsprechen, auf die dann mit dem SchILD-Client zugegriffen werden kann.</p><p>In großen Systemen, etwa kommunalen Rechenzentren oder kommerziellen Rechenzentren, könnten noch weitere Schemata in der MariaDB laufen, die dann anderen Schulen gehören oder gar nichts mit Schulen zu tun haben, etwa die kommunale Führerscheinstelle oder die Datenbank eines Unternehmens.</p><h3 id="was-ist-der-unterschied-zwischen-einem-root-datenbank-und-schild-nrw-3-benutzer" tabindex="-1">Was ist der Unterschied zwischen einem root-, Datenbank und SchILD-NRW 3-Benutzer? <a class="header-anchor" href="#was-ist-der-unterschied-zwischen-einem-root-datenbank-und-schild-nrw-3-benutzer" aria-label="Permalink to &quot;Was ist der Unterschied zwischen einem root-, Datenbank und SchILD-NRW 3-Benutzer?&quot;">​</a></h3><ul><li>Der <strong>Root-Benutzer</strong> verwaltet den gesamten MariaDB-Server. Er kann Datenbanken und weitere Datenbank-Benutzer anlegen oder löschen. Diese technischen Zugangsdaten gehören zur zuständigen IT. Ein vergessenes root-Kennwort muss administrativ wiederhergestellt werden; Ihr persönliches SchILD-Kennwort ersetzt diesen Zugang nicht.</li><li>Der <strong>Datenbank-Benutzer</strong> verbindet SchILD-NRW 3 mit der Schuldatenbank. Diese einzelne Datenbank heißt auch <strong>Schema</strong>; deshalb wird der Zugang auch Schema-Benutzer genannt. Im beschriebenen Aufbau erhält er Administrationsrechte auf dieses Schema. Welche Datenbanken er tatsächlich verwenden oder löschen darf, legen die MariaDB-Berechtigungen fest. Derselbe Benutzername kann für mehrere Schemata berechtigt sein. In den Beispielen heißt dieser technische Zugang <strong>svwsadmin</strong>.</li><li>Mit einem <strong>SchILD-NRW-3-Benutzer</strong> meldet sich eine Person zur täglichen Arbeit an. Die Benutzerverwaltung legt fest, welche Funktionen diese Person verwenden darf. Mit SchILD-Administrationsrechten stehen zusätzliche Funktionen der Programmoberfläche zur Verfügung. Diese Berechtigungen sind von den Rechten des technischen Datenbank-Zugangs zu unterscheiden.</li></ul><h3 id="wieso-wird-in-so-viele-unterschiedliche-ordner-installiert" tabindex="-1">Wieso wird in so viele unterschiedliche Ordner installiert? <a class="header-anchor" href="#wieso-wird-in-so-viele-unterschiedliche-ordner-installiert" aria-label="Permalink to &quot;Wieso wird in so viele unterschiedliche Ordner installiert?&quot;">​</a></h3><p>Um die Sicherheit des Betriebssystems zu gewährleisten, stattet Windows die unterschiedlichen Ordner mit unterschiedlichen Rechten aus. Der SVWS-Server und SchILD-NRW 3 fügen sich hier in diesem Sinne korrekt ein.</p><p>Für die Benutzung des SVWS-Servers und SchILD-NRW werden vier unterschiedliche Verzeichnisse verwendet.</p><ul><li>Das Verzeichnis, in dem der SVWS-Server <em>installiert</em> wird. In diesem Verzeichnis sollen Nutzer nichts ablegen können und keinen Zugriff darauf haben.</li><li>Das Verzeichnis, in dem der SVWS-Server die Datenbanken ablegt. In diesem Verzeichnis hat nur der Server Zugriff, Nutzer sollen hier nichts lesen oder verändern können.</li><li>Das Verzeichnis, in dem das reine Programm SchILD-NRW3 installiert wird. Nutzer haben hier keine Schreibrechte und es werden hier keine Arbeitsdaten erstellt.</li><li>Das Verzeichnis, in dem die SchILD-Daten liegen, zum Beispiel die Reports oder die Export- und Importdateien. Hier haben Nutzer für die tägliche Arbeit Zugriff.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=FAQ" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5914.</p>',15)])])}const m=n(a,[["render",s]]);export{g as __pageData,m as default};
